    add('Common Logarithms are logarithms with base 10: \\(y=\\log_{10}x\\) means \\(10^y=x\\)', 'عام لوگارتھم، اساس 10 والے لوگارتھم ہیں: \\(y=\\log_{10}x\\) کا مطلب \\(10^y=x\\) ہے', 'عام لوګاریتمونه د 10 په قاعده لوګاریتمونه دي: \\(y=\\log_{10}x\\) د \\(10^y=x\\) مانا لري');
    add('“Log x”, which is read “the logarithm of x”, is the answer to the question “to what exponent must 10 be raised to produce x?”', '“Log x”، جسے “x کا لوگارتھم” پڑھتے ہیں، اس سوال کا جواب ہے کہ “10 کو کس قوت پر اٹھائیں تاکہ x حاصل ہو؟”', '“Log x”، چې “د x لوګاریتم” لوستل کېږي، د دې پوښتنې ځواب دی چې “10 باید کوم توان ته پورته شي څو x ترلاسه شي؟”');
    add('Evaluate the following logarithmic functions: (a). log 10000 (b). log .01 (c). \\(\\log\\sqrt{10}=\\frac{1}{2}\\)', 'درج ذیل لوگارتھمی تفاعلوں کی قیمتیں معلوم کریں: (a). log 10000 (b). log .01 (c). \\(\\log\\sqrt{10}=\\frac{1}{2}\\)', 'د لاندې لوګاریتمي تابع ګانو ارزښتونه ومومئ: (a). log 10000 (b). log .01 (c). \\(\\log\\sqrt{10}=\\frac{1}{2}\\)');
    add('This is equal to: \\(\\log10000=\\log10^4=4\\log10=4\\)', 'یہ اس کے برابر ہے: \\(\\log10000=\\log10^4=4\\log10=4\\)', 'دا له دې سره برابر دی: \\(\\log10000=\\log10^4=4\\log10=4\\)');
    add('This is equal to: \\(\\log .01=\\log\\frac{1}{100}=\\log(10)^{-2}=-2\\log10=-2\\)', 'یہ اس کے برابر ہے: \\(\\log .01=\\log\\frac{1}{100}=\\log(10)^{-2}=-2\\log10=-2\\)', 'دا له دې سره برابر دی: \\(\\log .01=\\log\\frac{1}{100}=\\log(10)^{-2}=-2\\log10=-2\\)');
    add('c. This is equal to: \\(\\log\\sqrt{10}=\\log(10)^{\\frac{1}{2}}=\\frac{1}{2}\\log10=\\frac{1}{2}\\)', 'c. یہ اس کے برابر ہے: \\(\\log\\sqrt{10}=\\log(10)^{\\frac{1}{2}}=\\frac{1}{2}\\log10=\\frac{1}{2}\\)', 'c. دا له دې سره برابر دی: \\(\\log\\sqrt{10}=\\log(10)^{\\frac{1}{2}}=\\frac{1}{2}\\log10=\\frac{1}{2}\\)');
    add('The common logarithm is also called Briggsian logarithms and the natural logarithm is also called Napierian logarithms.', 'عام لوگارتھم کو برگسی لوگارتھم اور قدرتی لوگارتھم کو نیپیئرین لوگارتھم بھی کہتے ہیں۔', 'عام لوګاریتم ته بریګسي لوګاریتم او طبیعي لوګاریتم ته نېپیریایي لوګاریتم هم ویل کېږي.');
    add('Natural Logarithms are logarithms with base e: \\(y=\\ln x\\) means \\(e^y=x\\)', 'قدرتی لوگارتھم، اساس e والے لوگارتھم ہیں: \\(y=\\ln x\\) کا مطلب \\(e^y=x\\) ہے', 'طبیعي لوګاریتمونه د e په قاعده لوګاریتمونه دي: \\(y=\\ln x\\) د \\(e^y=x\\) مانا لري');
    add('“ln x”, which is read “the el-en of x”, is the answer to the question “to what exponent must e be raised to produce x?”', '“ln x”، جسے “x کا ایل این” پڑھتے ہیں، اس سوال کا جواب ہے کہ “e کو کس قوت پر اٹھائیں تاکہ x حاصل ہو؟”', '“ln x”، چې “د x اېل اېن” لوستل کېږي، د دې پوښتنې ځواب دی چې “e باید کوم توان ته پورته شي څو x ترلاسه شي؟”');
    add('\\(y=\\log_b x\\) means \\(b^y=x\\)', '\\(y=\\log_b x\\) کا مطلب \\(b^y=x\\) ہے', '\\(y=\\log_b x\\) د \\(b^y=x\\) مانا لري');
    add('“y = log_b x”, which is read “y is the logarithm of x to the base b”, is the answer to the question “to what power must b be raised to produce x?”', '“y = log_b x”، جسے “y، اساس b پر x کا لوگارتھم ہے” پڑھتے ہیں، اس سوال کا جواب ہے کہ “b کو کس قوت پر اٹھائیں تاکہ x حاصل ہو؟”', '“y = log_b x”، چې “y د b په قاعده د x لوګاریتم دی” لوستل کېږي، د دې پوښتنې ځواب دی چې “b باید کوم توان ته پورته شي څو x ترلاسه شي؟”');
    add('Common logarithmic: \\(\\log x=\\log_{10}x\\). Natural logarithmic: \\(\\ln x=\\log_e x\\)', 'عام لوگارتھمی صورت: \\(\\log x=\\log_{10}x\\)۔ قدرتی لوگارتھمی صورت: \\(\\ln x=\\log_e x\\)', 'عامه لوګاریتمي بڼه: \\(\\log x=\\log_{10}x\\). طبیعي لوګاریتمي بڼه: \\(\\ln x=\\log_e x\\)');
    add('If b, M and N are positive real numbers b ≠ 1, and p and x are also any positive real numbers, then:', 'اگر b، M اور N مثبت حقیقی اعداد ہوں، b ≠ 1 ہو، اور p اور x بھی کوئی مثبت حقیقی اعداد ہوں، تو:', 'که b، M او N مثبت حقیقي عددونه وي، b ≠ 1 وي، او p او x هم هر ډول مثبت حقیقي عددونه وي، نو:');
    for (const en of ['i. \\(\\log_b1=0\\)', 'ii. \\(\\log_b b=1\\)', 'iii. \\(\\log_b b^x=x\\)', 'iv. \\(b^{\\log_b x}=x\\), x > 0', 'v. \\(\\log_b MN=\\log_b M+\\log_b N\\)', 'vi. \\(\\log_b\\frac{M}{N}=\\log_b M-\\log_b N\\)', 'vii. \\(\\log_b M^p=p\\log_b M\\)', 'viii. \\(\\log_b M=\\log_b N\\), M = N']) same(en);
    add('Find x to four decimal places for the following indicated exponential functions: (a). \\(10^x=2\\) (b). \\(e^x=3\\)', 'درج ذیل قوت نمائی تفاعلوں کے لیے x کی قیمت چار اعشاری مقامات تک معلوم کریں: (a). \\(10^x=2\\) (b). \\(e^x=3\\)', 'د لاندې ورکړل شویو نمایي تابع ګانو لپاره د x ارزښت تر څلورو اعشاري ځایونو پورې ومومئ: (a). \\(10^x=2\\) (b). \\(e^x=3\\)');
    add('a. \\(10^x=2\\); \\(\\log10^x=\\log2\\), log of both sides; \\(x\\log10=\\log2\\), ∵ log 10 = 1; x = 0.3010', 'a. \\(10^x=2\\); \\(\\log10^x=\\log2\\)، دونوں طرف log لینے سے؛ \\(x\\log10=\\log2\\)، ∵ log 10 = 1؛ x = 0.3010', 'a. \\(10^x=2\\); \\(\\log10^x=\\log2\\)، د دواړو خواوو log په اخیستلو؛ \\(x\\log10=\\log2\\)، ∵ log 10 = 1؛ x = 0.3010');
    add('b. \\(e^x=3\\); \\(\\ln e^x=\\ln3\\), ln of both sides; \\(x\\ln e=\\ln3\\), ∵ ln e = 1; x = 1.0986', 'b. \\(e^x=3\\); \\(\\ln e^x=\\ln3\\)، دونوں طرف ln لینے سے؛ \\(x\\ln e=\\ln3\\)، ∵ ln e = 1؛ x = 1.0986', 'b. \\(e^x=3\\); \\(\\ln e^x=\\ln3\\)، د دواړو خواوو ln په اخیستلو؛ \\(x\\ln e=\\ln3\\)، ∵ ln e = 1؛ x = 1.0986');
    add('Two people with the covid-19 positive visited the campus of Peshawar University. The number of days T that it took for the corona virus to infect n people is given by', 'کووڈ-19 مثبت ہونے والے دو افراد نے پشاور یونیورسٹی کے کیمپس کا دورہ کیا۔ کورونا وائرس کے n افراد کو متاثر کرنے میں لگنے والے دنوں کی تعداد T یہ ہے', 'د کووید-19 مثبتې پایلې لرونکو دوو کسانو د پېښور پوهنتون له انګړ څخه لیدنه وکړه. د کورونا ویروس له خوا د n کسانو د اخته کولو د ورځو شمېر T په لاندې ډول ورکول کېږي');
    add('How many days will it take for the virus to infect a. 500 people? b. 5000 people?', 'وائرس کو کتنے دن لگیں گے تاکہ وہ a. 500 افراد؟ b. 5000 افراد کو متاثر کرے؟', 'ویروس به څو ورځې ونیسي څو a. 500 کسان؟ b. 5000 کسان اخته کړي؟');
    add('The number of days T that will take for the flu virus to infect n people is given by', 'فلو وائرس کے n افراد کو متاثر کرنے میں لگنے والے دنوں کی تعداد T یوں دی گئی ہے', 'د فلو ویروس له خوا د n کسانو د اخته کولو د ورځو شمېر T په لاندې ډول ورکول کېږي');
    add('The number of days that will take for the virus to infect 500 people, is obtained by putting n = 500 in equation (i):', 'وائرس کے 500 افراد کو متاثر کرنے میں لگنے والے دنوں کی تعداد، مساوات (i) میں n = 500 رکھنے سے حاصل ہوتی ہے:', 'د ویروس له خوا د 500 کسانو د اخته کولو د ورځو شمېر په (i) معادله کې د n = 500 په اېښودلو ترلاسه کېږي:');
    same('a. \\(T(500)=-1.43\\ln\\left(\\frac{10,000-500}{4998(500)}\\right)=-1.43\\ln\\left(\\frac{9500}{2499000}\\right)=-1.43\\ln(0.00380)\\)');
