    add('2.6.1 Representation of open interval, closed interval, half open and half closed intervals on the number line', '2.6.1 عددی خط پر کھلے، بند، نصف کھلے اور نصف بند وقفوں کی نمائندگی', '2.6.1 پر عددي کرښه د خلاص، تړلي، نیم خلاص او نیم تړلي واټنونو استازولي');
    add('The source prints 2.6.1 for both subsection headings on this page. Both printed labels are retained; the next heading on page 46 is 2.6.3.', 'ماخذ میں اس صفحے کے دونوں ذیلی عنوانات کے ساتھ 2.6.1 چھپا ہے۔ دونوں مطبوعہ نمبر برقرار ہیں؛ صفحہ 46 پر اگلا عنوان 2.6.3 ہے۔', 'سرچینې د دې پاڼې د دواړو فرعي سرلیکونو لپاره 2.6.1 چاپ کړی دی. دواړه چاپ شوي شمېرې ساتل شوې؛ پر 46 پاڼه راتلونکی سرلیک 2.6.3 دی.');
    add('“A set that consists of all the real numbers between two points is called an interval.”', '“وہ مجموعہ جو دو نقاط کے درمیان تمام حقیقی اعداد پر مشتمل ہو، وقفہ کہلاتا ہے۔”', '“هغه مجموعه چې د دوو نقطو ترمنځ ټول حقیقي عددونه پکې وي، واټن بلل کېږي.”');
    add('A special notation will be used to indicate an interval on the real number line.', 'حقیقی عددی خط پر وقفہ ظاہر کرنے کے لیے ایک خاص علامتی طریقہ استعمال کیا جائے گا۔', 'د حقیقي عددونو پر کرښه د واټن د ښودلو لپاره به ځانګړې نښه کارول کېږي.');
    add('For example, the interval including all numbers x, where −2 < x < 3 is written as (−2, 3). The parentheses indicate that the number −2 and 3 are not included.', 'مثلاً تمام ایسے اعداد x کا وقفہ جن کے لیے −2 < x < 3 ہو، (−2, 3) لکھا جاتا ہے۔ گول قوسین بتاتی ہیں کہ اعداد −2 اور 3 شامل نہیں ہیں۔', 'د بېلګې په توګه، د هغو ټولو x عددونو واټن چې −2 < x < 3 وي، د (−2, 3) په بڼه لیکل کېږي. ګرد قوسونه ښيي چې −2 او 3 عددونه پکې نه دي شامل.');
    add('If −2 and 3 are to be included in the interval, square brackets are used, as in [−2, 3].', 'اگر −2 اور 3 کو وقفے میں شامل کرنا ہو تو مربع قوسین استعمال ہوتی ہیں، جیسے [−2, 3]۔', 'که −2 او 3 په واټن کې شاملول غواړو، نو مربع قوسونه کارول کېږي، لکه [−2, 3].');
    add('The chart below shows several typical intervals, where a < b.', 'نیچے جدول میں چند عام وقفے دکھائے گئے ہیں، جہاں a < b ہے۔', 'لاندې جدول څو عادي واټنونه ښيي، چې a < b دی.');
    add('Inequality', 'نامساوات', 'نامساوات'); add('Interval Notation', 'وقفے کی علامتی صورت', 'د واټن نښه'); add('Explanation', 'وضاحت', 'تشریح');
    add('[a,b]: Closed', '[a,b]: بند', '[a,b]: تړلی'); add('[a,b): Half open/Closed', '[a,b): نصف کھلا/بند', '[a,b): نیم خلاص/تړلی'); add('(a,b]: Half Open/Closed', '(a,b]: نصف کھلا/بند', '(a,b]: نیم خلاص/تړلی'); add('(a,b): Open', '(a,b): کھلا', '(a,b): خلاص');
    add('Both a and b are included.', 'a اور b دونوں شامل ہیں۔', 'a او b دواړه شامل دي.'); add('a is included, b is not.', 'a شامل ہے، b شامل نہیں۔', 'a شامل دی، b نه دی.'); add('b is included, a is not.', 'b شامل ہے، a شامل نہیں۔', 'b شامل دی، a نه دی.'); add('Both a and b are not included.', 'a اور b دونوں شامل نہیں ہیں۔', 'a او b دواړه نه دي شامل.');
    add('Interval notation is also used to describe sets such as the set of all numbers x, with x ≥ −2. This interval is written [−2, ∞).', 'وقفے کی علامتی صورت ایسے مجموعوں کو ظاہر کرنے کے لیے بھی استعمال ہوتی ہے جیسے تمام اعداد x کا مجموعہ جن کے لیے x ≥ −2 ہو۔ یہ وقفہ [−2, ∞) لکھا جاتا ہے۔', 'د واټن نښه د هغو مجموعو د بیان لپاره هم کارول کېږي لکه د ټولو هغو x عددونو مجموعه چې x ≥ −2 وي. دا واټن [−2, ∞) لیکل کېږي.');
